import SwiftUI
import iREdFramework
import Charts

enum HeartRateMetric {
    case average, max, min

    var title: String {
        switch self {
        case .average: return "Average Heart Rate"
        case .max: return "Max Heart Rate"
        case .min: return "Min Heart Rate"
        }
    }
}

struct HeartRateChart: View {
    let data: [HeartRateHistoryItem]
    let metric: HeartRateMetric

    var body: some View {
        VStack(alignment: .leading) {
            Text(metric.title)
                .font(.headline)
                .padding(.bottom, 4)

            Chart {
                ForEach(data) { item in
                    switch metric {
                    case .average:
                        LineMark(
                            x: .value("Date", item.date),
                            y: .value("Heart Rate", item.average_hr)
                        )
                        .foregroundStyle(by: .value("Type", "Average"))
                        .symbol(by: .value("Type", "Average"))

                    case .max:
                        LineMark(
                            x: .value("Date", item.date),
                            y: .value("Heart Rate", item.max_hr)
                        )
                        .foregroundStyle(by: .value("Type", "Max"))
                        .symbol(by: .value("Type", "Max"))

                    case .min:
                        LineMark(
                            x: .value("Date", item.date),
                            y: .value("Heart Rate", item.min_hr)
                        )
                        .foregroundStyle(by: .value("Type", "Min"))
                        .symbol(by: .value("Type", "Min"))
                    }
                }
            }
            .chartYAxis {
                AxisMarks(position: .leading)
            }
            .frame(height: 200)
        }

y: .value("Heart Rate", item.min_hr)
                        )
                        .foregroundStyle(by: .value("Type", "Min"))
                        .symbol(by: .value("Type", "Min"))
                    }
                }
            }
            .chartYAxis {
                AxisMarks(position: .leading)
            }
            .frame(height: 200)
        }
        .padding()
        .background(Color.gray.opacity(0.1))
        .cornerRadius(12)
    }
}

struct HeartRateBeltView: View {
    @StateObject var ble = iREdBluetooth.shared
    @State var lastResult: String = "None"
    @State var historyData: [HeartRateHistoryItem] = []

    var body: some View {
        let belt = ble.iredDeviceData.heartRateData

        ScrollView {
            VStack(alignment: .leading, spacing: 8) {
                Text("--- DATA ---")
                Text("Name: \(belt.data.peripheralName ?? "nil")")

                Text("Is Connected: \(belt.state.isConnected.description)")
                Text("Is Paired: \(belt.state.isPaired.description)")
                Text("Is Pairing: \(belt.state.isPairing.description)")

                Text("Heart Rate: \(belt.data.heartrate ?? 0)")
                if let batteryPercentage = belt.data.batteryPercentage {
                    Text("Battery: \(batteryPercentage)%")
                } else {
                    Text("Battery: N/A")
                }

                Text("Last Command: \(lastResult)")

                Text("--- OPERATIONS ---")

                Group {
                    HStack {
                        Button("Start Pairing") {
                            ble.startPairing(to: .heartRateBelt)
                            lastResult = "Start Pairing"
                        }
                        Spacer()
                        Button("Stop Pairing") {
                            ble.stopPairing()
                            lastResult = "Stop Pairing"
                        }
                    }

                    HStack {

Button("Start Pairing") {
                            ble.startPairing(to: .heartRateBelt)
