//
//  BLEManager.swift
//  SmartHealth
//
//  Shared BLE state — wraps iREdBluetooth singleton for use across all views.
//

import SwiftUI
import Combine
import iREdFramework

/// Central BLE manager that holds the iREdBluetooth singleton.
/// Inject via `.environmentObject()` at the App level.
final class BLEManager: ObservableObject {
    let ble: iREdBluetooth

    init() {
        self.ble = iREdBluetooth.shared
    }
}

//
//  HeartRateHistoryView.swift
//  SmartHealth
//
//  Heart rate history — iOS native, Charts-backed, HIG-compliant.
//

import SwiftUI
import Charts

enum HeartRateMetric {
    case average, max, min

    var title: String {
        switch self {
        case .average: return "平均心率"
        case .max: return "最高心率"
        case .min: return "最低心率"
        }
    }

    var color: Color {
        switch self {
        case .average: return .red
        case .max: return .orange
        case .min: return .blue
        }
    }
}

struct HeartRateChart: View {
    let data: [HeartRateRecord]
    let metric: HeartRateMetric

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack {
                Circle()
                    .fill(metric.color)
                    .frame(width: 8, height: 8)
                Text(metric.title)
                    .font(.headline.weight(.semibold))
                Spacer()
                if let latest = data.first {
                    let value: Int = {
                        switch metric {
                        case .average: return latest.averageHR
                        case .max: return latest.maxHR
                        case .min: return latest.minHR
                        }
                    }()
                    Text("\(value) BPM")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }

            Chart {
                ForEach(data) { item in
                    let value: Int = {

case .min: return latest.minHR
                        }
                    }()
                    Text("\(value) BPM")
                        .font(.subheadline)
                        .foregroundStyle(.secondary)
                }
            }

            Chart {
                ForEach(data) { item in
                    let value: Int = {
                        switch metric {
                        case .average: return item.averageHR
                        case .max: return item.maxHR
                        case .min: return item.minHR
                        }
                    }()

                    LineMark(
                        x: .value("日期", item.date),
                        y: .value("心率", value)
                    )
                    .foregroundStyle(metric.color)
                    .symbol(Circle().strokeBorder(lineWidth: 1.5))
                    .interpolationMethod(.catmullRom)
                }
            }
            .chartYAxis {
                AxisMarks(position: .leading) { _ in
                    AxisGridLine(stroke: StrokeStyle(lineWidth: 0.5, dash: [4]))
                        .foregroundStyle(.quaternary)
                    AxisValueLabel()
                        .font(.caption2)
                        .foregroundStyle(.tertiary)
                }
            }
            .chartXAxis {
                AxisMarks { _ in
                    AxisValueLabel()
                        .font(.caption2)
                        .foregroundStyle(.tertiary)
                }
            }
            .frame(height: 180)
        }
        .padding(16)
        .background(.regularMaterial, in: RoundedRectangle(cornerRadius: 16))
    }
}

struct HeartRateHistoryView: View {
    @EnvironmentObject var historyStore: HistoryStore

    private var averageHR: Int {
        let records = historyStore.heartRateRecordsSorted
        guard !records.isEmpty else { return 0 }
        return records.map(\.averageHR).reduce(0, +) / records.count
    }

}
}

struct HeartRateHistoryView: View {
